<PackageInfo>

## Features

- Utilities for creating trigger-based combobox functionality
- Configurable trigger characters and patterns
- Atomic input completion, cancellation and history commands

</PackageInfo>

## Create a combobox plugin

<Steps>

### Installation

```bash
npm install platejs
npx shadcn@latest add @plate/inline-combobox
```

### Create input plugin

First, create an input plugin that will be inserted when the trigger is activated:

```tsx showLineNumbers
import { property } from 'platejs';
import { BaseComboboxPlugin } from 'platejs/combobox';
import { definePlatePlugin } from 'platejs/react';

export const TagInputPlugin = definePlatePlugin('tagInput', {
  dependencies: [BaseComboboxPlugin],
  editOnly: true,
  schema: {
    element: {
      type: 'tag_input',
      void: 'inline',
      properties: {
        trigger: property.string(),
        userId: property.string(),
      },
    },
  },
});
```

### Create main plugin

Create your main plugin with trigger metadata:

```tsx showLineNumbers
import { property } from 'platejs';
import { triggerCombobox, type TriggerComboboxPluginState } from 'platejs/combobox';
import { definePlatePlugin } from 'platejs/react';
import { TagInputPlugin } from './tag-input-plugin';

const initialState: TriggerComboboxPluginState = {
  trigger: '#',
  triggerPreviousCharPattern: /^\s?$/,
  createComboboxInput: () => ({
    children: [{ text: '' }],
    type: 'tag_input',
  }),
};

export const TagPlugin = definePlatePlugin('customTag', {
  dependencies: [TagInputPlugin],
  initialState,
  schema: {
    element: {
      type: 'tag',
      void: 'inline',
      properties: { value: property.string({ required: true }) },
    },
  },
  update: ({ tx, schema: { type } }) => ({
    insert: (value: string) => {
      tx.nodes.insert({ children: [{ text: '' }], type, value });
      tx.selection.move({ unit: 'offset' });
    },
  }),
}).extend(({ editor, store }) => ({
  commands: (context) => triggerCombobox(context, {
    editor,
    getState: () => store.get(),
    type: editor.plugin(TagInputPlugin).schema.type,
  }),
}));
```

- `schema.element`: Defines the plugin's element model behavior
- `schema.element.void: 'inline'`: Makes the tag an inline void and prevents editing inside it
- `initialState.trigger`: Character that triggers the combobox (in this case `#`)
- `initialState.triggerPreviousCharPattern`: RegExp pattern that must match the character before the trigger. `/^\s?$/` allows the trigger at the start of a line or after whitespace
- `initialState.createComboboxInput`: Function that creates the input element node when the trigger is activated

### Create component

Create the input element component using `InlineCombobox`:

```tsx showLineNumbers
import {
  type PlateElementProps,
  PlateElement,
  useEditorFocused,
  useEditorReadOnly,
  useElementSelected,
} from 'platejs/react';
import {
  InlineCombobox,
  InlineComboboxContent,
  InlineComboboxEmpty,
  InlineComboboxInput,
  InlineComboboxItem,
} from '@/components/editor/inline-combobox';
import { cn } from '@/lib/utils';
import { TagInputPlugin } from './tag-input-plugin';
import { TagPlugin } from './tag-plugin';

const tags = ['Frontend', 'Backend', 'Design', 'Urgent'];

export function TagInputElement(props: PlateElementProps<typeof TagInputPlugin>) {
  return (
    <PlateElement {...props} as="span">
      <InlineCombobox element={props.element} trigger="#">
        <InlineComboboxInput />
        <InlineComboboxContent>
          <InlineComboboxEmpty>No tags found</InlineComboboxEmpty>
          {tags.map((tag) => (
            <InlineComboboxItem
              key={tag}
              value={tag}
              onSelect={(tx) => tx.plugin(TagPlugin).insert(tag)}
            >
              #{tag}
            </InlineComboboxItem>
          ))}
        </InlineComboboxContent>
      </InlineCombobox>
      {props.children}
    </PlateElement>
  );
}

export function TagElement(props: PlateElementProps<typeof TagPlugin>) {
  const selected = useElementSelected();
  const focused = useEditorFocused();
  const readOnly = useEditorReadOnly();

  return (
    <PlateElement
      {...props}
      as="span"
      className={cn(
        'inline-block rounded-md bg-primary/10 px-1.5 py-0.5 align-baseline text-sm font-medium text-primary',
        !readOnly && 'cursor-pointer',
        selected && focused && 'ring-2 ring-ring'
      )}
    >
      #{props.element.value}
      {props.children}
    </PlateElement>
  );
}
```

### Add to editor

```tsx showLineNumbers
import { BaseCodeBlockPlugin } from 'platejs';
import { createEditor } from 'platejs/react';
import { TagPlugin } from './tag-plugin';
import { TagInputPlugin } from './tag-input-plugin';
import { TagElement, TagInputElement } from './tag-components';

const editor = createEditor({
  plugins: [
    TagPlugin.configure({
      component: TagElement,
      initialState: {
        triggerQuery: (editor) => {
          const codeBlock = editor.plugin(BaseCodeBlockPlugin);
          return !codeBlock.installed || !editor.read.nodes.some({ type: codeBlock.schema.type });
        },
      },
    }),
    TagInputPlugin.configure({ component: TagInputElement }),
  ],
});
```

- `initialState.triggerQuery`: Optional function to conditionally enable/disable the trigger based on editor state

